          "authorRole": "ANALISTA DE AVALUOS Y CATASTROS DE ASESORIA LEGAL 1",
          "note": "Revisada la documentación presentada por el señor CHIMBOLEMA GUAMAN JUAN ABRAHAN, se determina que el gravamen contine la palabra BORRADOR debiendo presentar el original del mismo, bajo tales circunstancias se emite criterio NO favorable .",
